// A durable pointer prevents an old draft or stale active flag hiding a newly saved block.
function selectedBlock(){
 db.blocks=Array.isArray(db.blocks)?db.blocks:[];
 const id=db.settings?.activeBlockId;
 const saved=id&&db.blocks.find(b=>b.id===id&&Array.isArray(b.weeks));
 if(saved){if(saved.status!=='active'){saved.status='active';db.blocks.filter(b=>b!==saved&&b.status==='active').forEach(b=>b.status='finished');persist()}return saved}
 const active=db.blocks.filter(b=>b.status==='active'&&Array.isArray(b.weeks)).at(-1);
 if(active){db.settings.activeBlockId=active.id;persist();return active}
 return null;
}
function commitActiveBlock(next){
 if(!next||!next.id||!Array.isArray(next.weeks)||!next.weeks.length)throw Error('Generated programme is incomplete');
 const old=JSON.stringify(db);
 try{
   db.blocks.forEach(b=>{if(b.status==='active')b.status='finished'});
   next.status='active';db.blocks.push(next);db.settings.activeBlockId=next.id;
   if(!persist())throw Error('Device storage did not accept your new programme');
   const recorded=JSON.parse(localStorage.getItem(KEY)||'{}');
   if(recorded.settings?.activeBlockId!==next.id||!recorded.blocks?.some(b=>b.id===next.id&&b.status==='active'))throw Error('Programme did not pass save verification');
   return true;
 }catch(err){db=JSON.parse(old);throw err}
}
