function recoveryAssessment(w){const r=w.recovery;if(!r)return {level:0,label:'Not assessed',message:'Complete an after workout check in to receive guidance.'};const effort=Number(r.effort),fatigue=Number(r.fatigue),energy=Number(r.energy),soreness=Number(r.soreness),pain=Number(r.pain),sleep=Number(r.sleep);const flags=[fatigue>=7,energy<=3,soreness>=7,sleep<=3,effort>=9];const count=flags.filter(Boolean).length;let level=0,label='Recovering normally',message='Allow normal recovery, eat and drink adequately, and adjust training if you feel worse.';if(count>=2||fatigue>=9||energy<=1){level=2;label='High recovery needs';message='Consider a rest day or very light movement, and avoid strenuous training until you feel recovered. Review your next planned session.'}else if(count>=1||fatigue>=5||soreness>=5||energy<=5){level=1;label='Take it easier';message='Consider an easier or shorter next session, prioritise sleep and food, and reassess before intensity.'}if(pain>=4){level=2;label='Pain warning';message='Avoid training through pain, especially running or heavy loading. Consider a qualified health professional if pain persists or affects movement.'}if(pain>=7){level=3;label='Significant pain reported';message='Stop painful training and seek prompt clinical advice. Seek urgent care if you cannot bear weight or have severe swelling, weakness or other concerning symptoms.'}return {level,label,message}}
